mapper.select:
SELECT cst_ym,dev_id,prj_id,asgn_id,aloc_ty_cd,mm_qty,tot_mm_qty,aloc_rt,lbr_cst_amt,
  drct_expns_amt,sls_amt,bill_untprc_amt,mm_ovr_yn,free_sprt_yn,pre_cntrct_yn
FROM cst.cst_aloc WHERE cst_ym=#{month}
AND prj_id=#{projectId}
ORDER BY dev_id,asgn_id NULLS LAST,cst_aloc_id

WITH expected AS (
  SELECT a.dev_id,a.prj_id,a.asgn_id FROM asgn.asgn a WHERE 
  AND a.prj_id=#{projectId}
  UNION SELECT s.dev_id,NULL::bigint,NULL::bigint FROM cst.mth_cst s WHERE s.cst_ym=#{month}
  AND EXISTS (SELECT 1 FROM asgn.asgn a WHERE a.dev_id=s.dev_id AND a.prj_id=#{projectId} AND )
  UNION SELECT e.dev_id,CASE WHEN e.dev_id IS NULL THEN e.prj_id ELSE NULL END,NULL::bigint
  FROM cst.drct_expns e WHERE e.expns_ym=#{month}
  AND (e.prj_id=#{projectId} OR (e.dev_id IS NOT NULL AND EXISTS
    (SELECT 1 FROM asgn.asgn a WHERE a.dev_id=e.dev_id AND a.prj_id=#{projectId} AND )))
)
SELECT count(*) FROM expected e WHERE NOT EXISTS (
  SELECT 1 FROM cst.cst_aloc c WHERE c.cst_ym=#{month}
  AND (e.dev_id IS NULL OR c.dev_id=e.dev_id)
  AND (e.prj_id IS NULL OR c.prj_id=e.prj_id OR c.aloc_ty_cd='INDIRECT')

)
